-- Wall
minetest.register_node("mood:wall", {
    description = "Waaalll",
    tiles = {"dh.png"},
    is_ground_content = false
})

-- Light
local function change_light(pos, node)
    local basename = minetest.registered_nodes[node.name].light_basename
    if not basename then return end

    if node.name == basename .. "_on" then
        minetest.set_node(pos, {name = basename .. "_off"})
    elseif node.name == basename .. "_off" then
        minetest.set_node(pos, {name = basename .. "_on"})
    end
    return true
end

minetest.register_node("mood:light_on", {
    light_source = 13,
    description = "Nice!",
    tiles = {"boko_light.jpg"},
    is_ground_content = false,
    on_punch = function(pos, node, _, _)
        change_light(pos, node)
    end,
    on_rightclick = function(pos, node, _, _, _)
        change_light(pos, node)
    end,
    light_basename = "mood:light"
})

minetest.register_node("mood:light_off", {
    description = "Nice!",
    tiles = {"boko_dark.jpg"},
    is_ground_content = false,
    on_punch = function(pos, node, _, _)
        change_light(pos, node)
    end,
    on_rightclick = function(pos, node, _, _, _)
        change_light(pos, node)
    end,
    light_basename = "mood:light"
})

-- Checkers
local function register_checker(index, func)
    local image_on = "amo_happy.jpg"
    local image_off = "amo_sad.jpg"
    if index % 2 == 1 then
        image_on = "nando_happy.jpg"
        image_off = "nando_sad.jpg"
    end
    local basename = "mood:checker_" .. tostring(index)

    minetest.register_node(basename .. "_on", {
        on_timer = func,
        on_construct = function(pos)
            minetest.get_node_timer(pos):start(0.5)
        end,
        tiles = {image_on},
        is_ground_content = false,
        description = "Happy happy happy",
        checker_basename = basename
    })

    minetest.register_node(basename .. "_off", {
        on_timer = func,
        on_construct = function(pos)
            minetest.get_node_timer(pos):start(0.5)
        end,
        tiles = {image_off},
        is_ground_content = false,
        description = "Sad sad sad",
        checker_basename = basename
    })
end

